export const translations: Record<AppLocale, Record<keyof typeof id, string>> = { id, en, zh, fr };
export type TranslationKey = keyof typeof id;

export function translate(locale: AppLocale, key: TranslationKey, params: Record<string, string | number> = {}): string {
  const message = translations[locale]?.[key] ?? translations.id[key] ?? key;
  return message.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? `{${name}}`));
}

export function roleKey(role: Role): TranslationKey { return `role.${role}` as TranslationKey; }
export function bookingStatusKey(status: BookingStatus): TranslationKey { return `status.${status}` as TranslationKey; }
export function invoiceStatusKey(status: InvoiceStatus): TranslationKey { return `status.${status}` as TranslationKey; }
export function invoiceSourceKey(source: "SERVICE" | "OVERTIME" | "PRIVATE_TUTORING"): TranslationKey { return `invoice.source.${source}` as TranslationKey; }
export function tenantPaymentStatusKey(status: TenantPaymentStatus): TranslationKey { return `status.${status}` as TranslationKey; }
export function tenantSubscriptionStatusKey(status: TenantSubscriptionStatus): TranslationKey { return `status.${status}` as TranslationKey; }
export function tenantSubscriptionFilterKey(status: TenantSubscriptionStatus): TranslationKey {
  switch (status) {
    case "TRIAL": return "tenant.filterTrial";
    case "PENDING_PAYMENT": return "tenant.filterDue";
    case "ACTIVE": return "tenant.filterActive";
    case "SUSPENDED": return "tenant.filterPaused";
    case "EXPIRED": return "tenant.filterExpired";
  }
}
export function tenantSubscriptionPlanKey(plan: TenantSubscriptionPlan): TranslationKey { return `plan.${plan}` as TranslationKey; }
const tenantReadinessIssueKeys: Record<TenantReadinessIssue, TranslationKey> = {
  SUBSCRIPTION_NOT_ACTIVE: "tenantReadiness.issueSubscription",
  STAFF_ADMIN_REQUIRED: "tenantReadiness.issueStaffAdmin",
  ACTIVE_BRANCH_REQUIRED: "tenantReadiness.issueBranch",
  ACTIVE_CLASSROOM_REQUIRED: "tenantReadiness.issueClassroom",
  ACTIVE_SERVICE_PLAN_REQUIRED: "tenantReadiness.issueServicePlan",
  BRANCH_CAPACITY_REQUIRED: "tenantReadiness.issueBranchCapacity",
  PAYMENT_INSTRUCTION_REQUIRED: "tenantReadiness.issuePaymentInstruction",
};
export function tenantReadinessIssueKey(issue: TenantReadinessIssue): TranslationKey { return tenantReadinessIssueKeys[issue]; }
export function servicePlanTypeKey(type: ServicePlanType): TranslationKey { return `booking.${type.toLowerCase()}` as TranslationKey; }
const goalDomainKeys: Record<GoalDomain, TranslationKey> = { KEMANDIRIAN: "goals.categoryKemandirian", BAHASA_KOMUNIKASI: "goals.categoryBahasaKomunikasi", KOGNITIF: "goals.categoryKognitif", MOTORIK_HALUS: "goals.categoryMotorikHalus", MOTORIK_KASAR: "goals.categoryMotorikKasar", SOSIAL_EMOSI: "goals.categorySosialEmosi" };
export function goalDomainKey(domain: GoalDomain): TranslationKey { return goalDomainKeys[domain]; }
export function goalPickerLabel(t: (key: TranslationKey, params?: Record<string, string | number>) => string, domain: GoalDomain, name: string): string {
  const domainLabel = t(goalDomainKey(domain));
  return name.trim().toLowerCase() === domainLabel.trim().toLowerCase() ? domainLabel : `${domainLabel} · ${name}`;
}
